import{_ as t,c as a,o as i,aj as n}from"./chunks/framework.CDhdelVI.js";const c=JSON.parse('{"title":"Yogurt Naan","description":"Soft skillet naan with yogurt and milk, with enough extensibility for blistered, tender flatbreads at home.","frontmatter":{"title":"Yogurt Naan","description":"Soft skillet naan with yogurt and milk, with enough extensibility for blistered, tender flatbreads at home.","head":[["meta",{"name":"description","content":"Soft skillet naan with yogurt and milk, with enough extensibility for blistered, tender flatbreads at home."}],["meta",{"property":"og:title","content":"Yogurt Naan"}],["meta",{"property":"og:description","content":"Soft skillet naan with yogurt and milk, with enough extensibility for blistered, tender flatbreads at home."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:url","content":"https://kitchenratio.com/recipes/naan.html"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Yogurt Naan"}],["meta",{"name":"twitter:description","content":"Soft skillet naan with yogurt and milk, with enough extensibility for blistered, tender flatbreads at home."}],["link",{"rel":"canonical","href":"https://kitchenratio.com/recipes/naan.html"}]]},"headers":[],"relativePath":"recipes/naan.md","filePath":"recipes/naan.md"}'),r={name:"recipes/naan.md"};function l(o,e,s,h,d,g){return i(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="yogurt-naan" tabindex="-1">Yogurt Naan <a class="header-anchor" href="#yogurt-naan" aria-label="Permalink to “Yogurt Naan”">​</a></h1><p>This naan is designed for home cooks using a hot skillet or steel, not a tandoor. The yogurt adds tenderness, the milk rounds out the crumb, and the dough stays easy to shape. Use the <a href="https://kitchenratio.com/calculator/flatbread/naan" target="_blank" rel="noreferrer">KitchenRatio Calculator</a> to scale any batch.</p><h2 id="baker-s" tabindex="-1">Baker&#39;s % <a class="header-anchor" href="#baker-s" aria-label="Permalink to “Baker&#39;s %”">​</a></h2><ul><li><strong>Flour</strong> - 100%</li><li><strong>Milk</strong> - 40%</li><li><strong>Yogurt</strong> - 20%</li><li><strong>Salt</strong> - 2%</li><li><strong>Oil</strong> - 4%</li><li><strong>Sugar</strong> - 2%</li><li><strong>Instant dry yeast</strong> - 1%</li></ul><h2 id="ingredients-example-batch" tabindex="-1">Ingredients (Example Batch) <a class="header-anchor" href="#ingredients-example-batch" aria-label="Permalink to “Ingredients (Example Batch)”">​</a></h2><ul><li><strong>Flour</strong> - 500g (100%)</li><li><strong>Milk</strong> - 200g (40%)</li><li><strong>Plain yogurt</strong> - 100g (20%)</li><li><strong>Salt</strong> - 10g (2%)</li><li><strong>Oil</strong> - 20g (4%)</li><li><strong>Sugar</strong> - 10g (2%)</li><li><strong>Instant dry yeast</strong> - 5g (1%)</li></ul><p>Need a scale? <a href="https://amzn.to/48F9DfT" target="_blank" rel="noreferrer">KitchenAid Digital Scale</a>.</p><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>This batch usually makes <strong>8 naan</strong> at about <strong>106g dough each</strong>.</p></div><hr><h2 id="procedure" tabindex="-1">Procedure <a class="header-anchor" href="#procedure" aria-label="Permalink to “Procedure”">​</a></h2><h3 id="_1-mixing" tabindex="-1">1. Mixing <a class="header-anchor" href="#_1-mixing" aria-label="Permalink to “1. Mixing”">​</a></h3><ul><li>Combine flour, yeast, sugar, yogurt, milk, and oil.</li><li>Mix until shaggy, then rest 10 minutes.</li><li>Add salt and knead until smooth and elastic, about <strong>6-8 minutes</strong>.</li></ul><h3 id="_2-bulk-fermentation" tabindex="-1">2. Bulk Fermentation <a class="header-anchor" href="#_2-bulk-fermentation" aria-label="Permalink to “2. Bulk Fermentation”">​</a></h3><ul><li>Cover and let rise at room temperature until noticeably puffy, usually <strong>60-90 minutes</strong>.</li></ul><h3 id="_3-divide-and-rest" tabindex="-1">3. Divide And Rest <a class="header-anchor" href="#_3-divide-and-rest" aria-label="Permalink to “3. Divide And Rest”">​</a></h3><ul><li>Divide into <strong>8 pieces</strong> and shape into balls.</li><li>Cover and rest <strong>20-30 minutes</strong> so the dough relaxes.</li></ul><h3 id="_4-shape" tabindex="-1">4. Shape <a class="header-anchor" href="#_4-shape" aria-label="Permalink to “4. Shape”">​</a></h3><ul><li>Roll or stretch each piece into an oval.</li><li>Keep the center a little thinner than the edges for fast puffing and blistering.</li></ul><h3 id="_5-cook" tabindex="-1">5. Cook <a class="header-anchor" href="#_5-cook" aria-label="Permalink to “5. Cook”">​</a></h3><ul><li>Heat a cast iron skillet, steel, or heavy pan over medium-high to high heat until fully hot.</li><li>Cook one naan at a time until the first side bubbles and blisters, about <strong>45-60 seconds</strong>.</li><li>Flip and cook the second side until browned in spots and cooked through, another <strong>30-60 seconds</strong>.</li></ul><h3 id="_6-finish" tabindex="-1">6. Finish <a class="header-anchor" href="#_6-finish" aria-label="Permalink to “6. Finish”">​</a></h3><ul><li>Brush lightly with melted butter or ghee if you want a softer finish.</li><li>Stack under a towel to keep warm and flexible.</li></ul><h2 id="what-to-adjust-first" tabindex="-1">What To Adjust First <a class="header-anchor" href="#what-to-adjust-first" aria-label="Permalink to “What To Adjust First”">​</a></h2><ul><li><strong>Not soft enough</strong>: shorten cook time slightly or brush with butter after cooking.</li><li><strong>Tearing while shaping</strong>: give the dough more bench rest.</li><li><strong>Too slack</strong>: reduce milk slightly or chill the dough for 10-15 minutes before shaping.</li></ul><h2 id="related-guides" tabindex="-1">Related Guides <a class="header-anchor" href="#related-guides" aria-label="Permalink to “Related Guides”">​</a></h2><ul><li><a href="/guides/enrichment.html">Enrichment</a></li><li><a href="/guides/hydration.html">Hydration</a></li><li><a href="/guides/yield-planner.html">Yield Planner</a></li></ul><h2 id="get-the-gear" tabindex="-1">Get the Gear <a class="header-anchor" href="#get-the-gear" aria-label="Permalink to “Get the Gear”">​</a></h2><ul><li><a href="/guides/baking-gear-and-ingredients.html">Baking Gear &amp; Ingredients</a></li></ul><blockquote><p><strong>Affiliate Disclaimer</strong> This post contains affiliate links. As an Amazon Associate, I earn from qualifying purchases. If you click on a link and make a purchase, I may receive a small commission at no extra cost to you.</p></blockquote>',29)])])}const m=t(r,[["render",l]]);export{c as __pageData,m as default};
